rule Suspicious_PNG_Upload {
    meta:
        description = "Detects processes uploading large PNG files with embedded data signatures"
        author = "SOC Team"
        date = "2026-04-09"
    strings:
        $png_header = { 89 50 4E 47 0D 0A 1A 0A }
        $lsb_pattern = { [100-500] (00|FF) [0-1] (00|FF) [0-1] (00|FF) }
    condition:
        $png_header at 0 and
        filesize > 50MB and
        #lsb_pattern > 50
}

